using System.Text.Json.Nodes;
namespace RisingLands;
public static class ImprovementsV72Tests {
 static int checks;
 static void Check(bool ok,string label){checks++;if(!ok)throw new Exception("FAIL v72: "+label);Console.WriteLine("PASS v72: "+label);}
 static void Until(Simulation s,Func<bool> done,int limit=12000){for(int i=0;i<limit&&!done();i++)s.Step();Check(done(),"bounded task completes");}
 static Simulation Fixture(string root){var s=ImprovementsV67Tests.Fixture(root);for(int i=0;i<4;i++)while(s.GrantTestTechnology(i)){}for(int j=0;j<30;j++)foreach(int k in new[]{0,1,2})s.GrantTestResource(k);return s;}
 public static void Run(string root){
  foreach(int type in new[]{0,1,2,3,4,8,25}){var s=ImprovementsV67Tests.Fixture(root);var a=s.World.Units.First(a=>a.Type==0&&a.Owner==0);a.Type=type;a.Satiety=2;a.FatigueClock=s.FatiguePeriod(a)-1;a.Route.Clear();s.Step();Check(a.Satiety==1&&a.FatigueClock==0,"idle living military hunger "+type);}
  foreach(int type in Enumerable.Range(11,14)){var s=ImprovementsV67Tests.Fixture(root);var a=s.World.Units.First(a=>a.Owner==0);a.Type=type;a.Satiety=2;a.FatigueClock=2999;s.Step();Check(a.Satiety==2&&a.FatigueClock==2999,"native machine exemption "+type);}
  var hunger=ImprovementsV67Tests.Fixture(root);var troop=hunger.World.Units.First(a=>a.Type==0&&a.Owner==0);int guard=6+6*256;troop.X=6*1024;troop.Y=6*1024;troop.Satiety=0;troop.Route.Clear();hunger.Step();Check(hunger.Feeding(troop)&&hunger.Hunger.Trips.Single(t=>t.Slot==troop.Slot).ReturnCell==guard,"idle guard preserves position while eating");string pending=hunger.Serialize();var copy=ImprovementsV67Tests.Fixture(root);copy.Restore(pending);Check(copy.Serialize()==pending,"feeding guard reload");Until(hunger,()=>troop.Satiety>0);Check(hunger.Hunger.Consumed[0]==1,"soldier consumes one meal");Until(hunger,()=>troop.Route.Count==0);Check(troop.X==6*1024&&troop.Y==6*1024,"soldier returns to guard position");
  var starve=ImprovementsV67Tests.Fixture(root,false);Array.Clear(starve.World.Resources);troop=starve.World.Units.First(a=>a.Type==0&&a.Owner==0);troop.Satiety=0;troop.FatigueClock=starve.FatiguePeriod(troop)-1;int hp=troop.Health;starve.Step();Check(troop.Health==hp-20,"idle troop starvation damage");troop.Health=20;troop.FatigueClock=starve.FatiguePeriod(troop)-1;starve.Step();Check(troop.Health==0&&!starve.Feeding(troop),"idle troop starvation death");
  foreach(int orientation in new[]{0,1}){
   var s=Fixture(root);var builder=s.World.Units.First(a=>a.Type==7&&a.Owner==0);int anchor=40+40*256,delta=orientation==0?1:256;builder.X=39*1024;builder.Y=39*1024;
   Check(s.PlacementError(builder,12,anchor)!=null,"gate cannot be built without wall");Check(s.PlanWall(builder,anchor-delta,anchor+delta)==3,"wall line created");Check(s.PlacementError(builder,12,anchor)!=null,"unfinished wall cannot receive gate");Until(s,()=>s.Constructions.All(s.Complete));Check(s.GateOrientationAt(anchor)==orientation,"native gate orientation "+orientation);int source=s.World.Buildings.Single(b=>b.Type==9&&b.Cell==anchor).Slot;
   Check(s.StartConstruction(builder,12,anchor),"gate replaces completed own wall "+orientation);var gate=s.Constructions.Last();Check(gate.ReplacesWall==source&&gate.GateOrientation==orientation,"replacement and direction recorded");Check(!s.Passable(40,40),"gate work blocks passage");pending=s.Serialize();copy=Fixture(root);copy.Restore(pending);Check(copy.Serialize()==pending,"pending gate roundtrip");Until(s,()=>s.Complete(gate));Check(s.World.Buildings.All(b=>b.Slot!=source)&&s.World.Buildings.Single(b=>b.Cell==anchor).Type==12,"completed gate removes active wall only");Check(!s.Passable(40,40),"completed gate starts closed");pending=s.Serialize();copy=Fixture(root);copy.Restore(pending);Check(copy.Serialize()==pending&&!copy.Passable(40,40),"closed gate roundtrip and collision");
   Check(s.ToggleGate(gate.Id),"open gate command");Check(!s.Passable(40,40),"opening gate blocks until raised");pending=s.Serialize();copy=Fixture(root);copy.Restore(pending);for(int i=0;i<20;i++){s.Step();copy.Step();}Check(copy.Serialize()==s.Serialize(),"opening gate resumes deterministically");Check(s.Passable(40,40)&&!s.WallAt(anchor),"open gate permits crossing");troop=s.World.Units.First(a=>a.Type==0&&a.Owner==0);Check(s.Order(troop,40,40),"troop routes into open gate");Until(s,()=>troop.Route.Count==0);Check(!s.ToggleGate(gate.Id),"gate cannot close on unit");troop.X=38*1024;troop.Y=38*1024;Check(s.ToggleGate(gate.Id)&&!s.Passable(40,40),"closing immediately blocks new routes");for(int i=0;i<20;i++)s.Step();Check(gate.GateFrame==15,"original closed frame restored");pending=s.Serialize();copy=Fixture(root);copy.Restore(pending);Check(copy.Serialize()==pending,"closed upgrade retains conservation and save state");var bad=JsonNode.Parse(pending)!;bad["Constructions"]!.AsArray().Last()!["ReplacesWall"]=-1;try{s.Restore(bad.ToJsonString());throw new Exception("forged gate accepted");}catch(InvalidDataException){}Check(s.Serialize()==pending,"invalid gate replacement rejected atomically");
  }
  
  Simulation NativeFixture(){var baseline=Fixture(root);int cell=50+50*256;baseline.World.Buildings.Add(new(990,9,0,cell-1));baseline.World.Buildings.Add(new(991,12,0,cell));baseline.World.Buildings.Add(new(992,9,0,cell+1));return new Simulation(baseline.World,baseline.Campaign);}
  var existing=NativeFixture();Check(existing.ToggleGate(991),"pre-existing native gate opens");for(int i=0;i<20;i++)existing.Step();Check(existing.Passable(50,50),"pre-existing gate overrides original collision");copy=NativeFixture();copy.Restore(existing.Serialize());Check(copy.Serialize()==existing.Serialize()&&copy.Passable(50,50),"pre-existing gate controls reload");
  Simulation GrowthFixture(){var baseline=ImprovementsV67Tests.Fixture(root);int cell=4+4*256;baseline.World.Quantities[cell]=1;baseline.World.Tiles[cell]=157;return new Simulation(baseline.World,baseline.Campaign);}
  var grown=GrowthFixture();var eater=grown.World.Units.First(a=>a.Type==5&&a.Owner==0);eater.Satiety=0;grown.Step();Until(grown,()=>eater.Satiety>0);Check(grown.World.Objects[4+4*256]==0&&grown.SpawnPlant(4+4*256,0),"eaten ground food can become growing vegetation");copy=GrowthFixture();copy.Restore(grown.Serialize());Check(copy.Serialize()==grown.Serialize(),"vegetation on eaten pile reloads with food conservation");
  var restricted=Fixture(root);var wallBuilder=restricted.World.Units.First(a=>a.Type==7&&a.Owner==0);int center=60+60*256;restricted.World.Buildings.Add(new(980,9,1,center));restricted.World.Buildings.Add(new(981,9,1,center-1));restricted.World.Buildings.Add(new(982,9,1,center+1));Check(restricted.PlacementError(wallBuilder,12,center)!=null,"cannot upgrade enemy wall");restricted.World.Buildings.RemoveAll(b=>b.Slot>=980);restricted.World.Buildings.Add(new(980,9,0,center));restricted.World.Buildings.Add(new(981,9,0,center-1));restricted.World.Buildings.Add(new(982,9,0,center+256));restricted=new Simulation(restricted.World,restricted.Campaign);Check(restricted.PlacementError(wallBuilder,12,center)!=null,"corner without opposite neighbours rejects gate");
  Check(GatePresentation.Data.Frames.Count==64&&GatePresentation.Data.Stages.Count==202,"all original frames and construction stages packaged");Console.WriteLine("ALL v72 TESTS PASSED: "+checks);
 }
}
